insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aumento de pena nos crimes patrimoniais cometidos contra instituições financeiras e prestadores de serviço de segurança privada (Estatuto da Segurança Privada): penas aumentadas de 1/3 até o dobro. (Na plataforma, o texto desta unidade traz em seguida a violação de direito autoral, art. 184, com detenção de 3 meses a 1 ano ou multa; reclusão de 2 a 4 anos e multa na reprodução com intuito de lucro e no oferecimento ao público por sistema que permita a seleção da obra; e a exceção do §4º para limitações ao direito de autor e cópia privada de um só exemplar sem lucro.)', '["Crimes do título contra instituições financeiras e prestadores de segurança privada: aumento de 1/3 até o dobro.","Violação de direito autoral: detenção de 3 meses a 1 ano, ou multa; formas com intuito de lucro: reclusão de 2 a 4 anos e multa.","§4º: não se aplica às limitações ao direito de autor nem à cópia privada de um só exemplar sem lucro."]'::jsonb, '["O aumento é de 1/3 até o DOBRO.","A violação de direito autoral com intuito de lucro tem pena de reclusão."]'::jsonb, 'Roubo a uma agência bancária: pena aumentada nos termos do art. 183-A.', '["Assertiva que fixa o aumento de 183-A em até metade erra: é de um terço até o dobro."]'::jsonb, '[]'::jsonb, '["Art. 186 (ação penal nos crimes contra a propriedade imaterial)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-183-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ação penal nos crimes contra a propriedade imaterial: procede-se mediante queixa nos crimes do caput do art. 184; ação penal pública incondicionada nos crimes dos §§1º e 2º do art. 184; ação pública incondicionada nos crimes cometidos em desfavor de entidades de direito público, autarquia, empresa pública, sociedade de economia mista ou fundação pública; e ação pública condicionada à representação nos crimes do §3º do art. 184.', '["Caput do art. 184: queixa.","§§1º e 2º do art. 184: pública incondicionada.","Contra entes públicos: pública incondicionada.","§3º do art. 184: pública condicionada à representação."]'::jsonb, '["Quatro regimes de ação penal: queixa; incondicionada; incondicionada (entes públicos); condicionada (§3º)."]'::jsonb, 'Violação simples de direito autoral (caput): o titular deve oferecer queixa.', '["Assertiva que torna pública incondicionada a ação do caput do art. 184 erra: é por queixa."]'::jsonb, '[]'::jsonb, '["Art. 183-A (texto do art. 184)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-186'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Atentado contra a liberdade de trabalho: constranger alguém, mediante violência ou grave ameaça, a exercer ou não exercer arte, ofício, profissão ou indústria, ou a trabalhar ou não trabalhar durante certo período ou em determinados dias (detenção de 1 mês a 1 ano e multa, além da pena da violência); ou a abrir ou fechar o seu estabelecimento de trabalho, ou a participar de parede ou paralisação de atividade econômica (detenção de 3 meses a 1 ano e multa, além da violência).', '["I – constranger a exercer ou não exercer profissão ou a trabalhar ou não: detenção de 1 mês a 1 ano e multa.","II – constranger a abrir ou fechar estabelecimento ou a participar de greve ou paralisação: detenção de 3 meses a 1 ano e multa.","Em ambos, além da pena da violência."]'::jsonb, '["Exige violência ou grave ameaça."]'::jsonb, 'Ameaçar um comerciante para que feche o estabelecimento em dia de paralisação.', '["Assertiva que dispensa violência ou grave ameaça no art. 197 erra."]'::jsonb, '[]'::jsonb, '["Arts. 198 a 200"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-197'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

