insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aliciamento de trabalhadores de um local para outro do território nacional: aliciar trabalhadores com o fim de levá-los de uma para outra localidade. Pena: detenção de 1 a 3 anos e multa. Incorre na mesma pena quem recruta trabalhadores fora da localidade de execução do trabalho, dentro do território nacional, mediante fraude ou cobrança de qualquer quantia do trabalhador, ou não assegura condições do seu retorno ao local de origem. A pena aumenta de um sexto a um terço se a vítima é menor de 18 anos, idosa, gestante, indígena ou portadora de deficiência física ou mental.', '["Aliciar trabalhadores para levá-los de uma localidade a outra do país.","Detenção de 1 a 3 anos e multa.","§1º: recrutar fraudulentamente ou cobrando quantia; ou não assegurar o retorno.","§2º: aumento de 1/6 a 1/3 (menor de 18, idosa, gestante, indígena, pessoa com deficiência)."]'::jsonb, '["Dentro do território nacional (diferente do art. 206)."]'::jsonb, 'Aliciar trabalhadores rurais para outro estado e deixá-los sem condições de retornar.', '["Assertiva que aplica o art. 207 ao aliciamento para o exterior erra: esse é o art. 206."]'::jsonb, '[]'::jsonb, '["Art. 206"]'::jsonb, 'under_review', 'claude'
