insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estupro de vulnerável: ter conjunção carnal ou praticar outro ato libidinoso com menor de 14 anos. Pena: reclusão de 10 a 18 anos e multa (texto atual). Incorre na mesma pena quem pratica as ações com alguém que, por enfermidade ou deficiência mental, não tem o necessário discernimento ou que, por qualquer outra causa, não pode oferecer resistência. Lesão corporal grave: reclusão de 12 a 24 anos e multa; morte: reclusão de 20 a 40 anos e multa. É absoluta a presunção de vulnerabilidade, inadmissível relativizá-la (§4º-A). As penas se aplicam independentemente do consentimento da vítima, de sua experiência sexual e de outras circunstâncias do §5º.', '["Caput: menor de 14 anos: reclusão de 10 a 18 anos e multa.","§1º: pessoa sem discernimento por enfermidade ou deficiência, ou sem poder de resistência: mesma pena.","§3º: lesão grave: 12 a 24 anos e multa.","§4º: morte: 20 a 40 anos e multa.","§4º-A: presunção de vulnerabilidade ABSOLUTA.","§5º: aplica-se independentemente do consentimento da vítima e de outras circunstâncias."]'::jsonb, '["A vulnerabilidade do menor de 14 anos é ABSOLUTA: o consentimento é irrelevante.","Crime hediondo."]'::jsonb, 'Relação sexual com adolescente de 13 anos, ainda que ele diga consentir: estupro de vulnerável.', '["Assertiva que admite afastar o crime pelo consentimento do menor de 14 anos erra: a presunção é absoluta."]'::jsonb, '[{"termo":"Vulnerável","significado":"Menor de 14 anos ou pessoa sem discernimento ou sem poder de resistência."}]'::jsonb, '["Art. 213","Art. 218"]'::jsonb, 'under_review', 'claude'
