insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Divulgação de cena de estupro, de sexo, nudez ou pornografia: oferecer, trocar, disponibilizar, transmitir, vender ou expor à venda, distribuir, publicar ou divulgar, por qualquer meio, fotografia, vídeo ou outro registro audiovisual que contenha cena de estupro ou de estupro de vulnerável, ou que faça apologia ou induza a sua prática, ou, sem o consentimento da vítima, cena de sexo, nudez ou pornografia. Pena: reclusão de 4 a 10 anos e multa (texto atual), se o fato não constitui crime mais grave. A pena aumenta de 1/3 a 2/3 se o agente mantém ou manteve relação íntima de afeto com a vítima ou age com fim de vingança ou humilhação. Não há crime em publicação de natureza jornalística, científica, cultural ou acadêmica com recurso que impossibilite a identificação da vítima, ressalvada autorização prévia se maior de 18 anos.', '["Condutas: oferecer, trocar, disponibilizar, transmitir, vender, expor à venda, distribuir, publicar ou divulgar.","Objeto: cena de estupro ou apologia, ou cena de sexo, nudez ou pornografia sem consentimento da vítima.","Pena: reclusão de 4 a 10 anos e multa, se não houver crime mais grave.","§1º: aumento de 1/3 a 2/3 (relação íntima de afeto, vingança ou humilhação).","§2º: exclusão do crime em publicação jornalística, científica, cultural ou acadêmica sem identificar a vítima."]'::jsonb, '["Pena aumentada na ''vingança pornográfica'' (relação de afeto, fim de vingança ou humilhação)."]'::jsonb, 'Ex-namorado divulga em redes sociais vídeo íntimo da ex-companheira para humilhá-la: art. 218-C, com aumento.', '["Assertiva que exige que a vítima seja maior de 18 anos para o art. 218-C erra: o consentimento é a base para cena de sexo, nudez ou pornografia, e a cena de estupro é crime por si."]'::jsonb, '[]'::jsonb, '["Art. 216-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-218-c'
