insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ação penal nos crimes contra a liberdade sexual e contra vulneráveis (Capítulos I e II do Título): procede-se mediante ação penal pública incondicionada. O parágrafo único está revogado.', '["Ação penal pública INCONDICIONADA nos Capítulos I e II do Título."]'::jsonb, '["Hoje a regra é ação pública incondicionada (mudança de 2018)."]'::jsonb, 'O Ministério Público denuncia o autor de estupro independentemente de representação da vítima.', '["Assertiva que exige representação da vítima para o estupro erra: a ação é pública incondicionada."]'::jsonb, '[]'::jsonb, '["Arts. 213 a 218-C"]'::jsonb, 'under_review', 'claude'
