insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aumentos de pena nos crimes sexuais: aumenta-se de quarta parte se o crime é cometido com o concurso de 2 ou mais pessoas; de metade se o agente é ascendente, padrasto, madrasta, tio, irmão, cônjuge, companheiro, tutor, curador, preceptor ou empregador da vítima ou por qualquer título tem autoridade sobre ela; e de 1/3 a 2/3 se o crime é praticado mediante concurso de 2 ou mais agentes (estupro coletivo) ou para controlar o comportamento social ou sexual da vítima (estupro corretivo).', '["I – concurso de 2 ou mais pessoas: aumento de quarta parte.","II – agente com autoridade sobre a vítima (ascendente, padrasto, tutor, empregador etc.): aumento de metade.","IV, a – estupro coletivo: aumento de 1/3 a 2/3.","IV, b – estupro corretivo (controlar comportamento social ou sexual): 1/3 a 2/3."]'::jsonb, '["Concurso de 2 ou mais pessoas: quarta parte (inciso I) OU, no estupro coletivo, 1/3 a 2/3 (inciso IV, a): cuidado com a aplicação.","O inciso III está revogado."]'::jsonb, 'Padrasto que comete estupro contra a enteada tem a pena aumentada de metade.', '["Assertiva que fixa em dobro o aumento pelo agente com autoridade sobre a vítima erra: é de metade."]'::jsonb, '[]'::jsonb, '["Art. 213","Art. 234-A"]'::jsonb, 'under_review', 'claude'
