insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Mediação para servir a lascívia de outrem: induzir alguém a satisfazer a lascívia de outrem. Pena: reclusão de 1 a 3 anos. Se a vítima é maior de 14 e menor de 18 anos, ou se o agente é seu ascendente, descendente, cônjuge ou companheiro, irmão, tutor, curador ou pessoa a quem esteja confiada para educação, tratamento ou guarda: reclusão de 2 a 5 anos. Com violência, grave ameaça ou fraude: reclusão de 2 a 8 anos, além da pena da violência. Com fim de lucro: também multa.', '["Caput: reclusão de 1 a 3 anos.","§1º: vítima entre 14 e 18 anos ou agente com vínculo de cuidado: reclusão de 2 a 5 anos.","§2º: violência, grave ameaça ou fraude: reclusão de 2 a 8 anos.","§3º: fim de lucro: também multa."]'::jsonb, '["Vítima menor de 14 anos: outro crime (art. 218)."]'::jsonb, 'Aliciar mulher adulta para que satisfaça a lascívia de outra pessoa.', '["Assertiva que aplica o caput do art. 227 a vítima menor de 14 anos erra: o art. 218 trata desse caso."]'::jsonb, '[]'::jsonb, '["Art. 218","Art. 228"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-227'
