insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Favorecimento da prostituição ou de outra forma de exploração sexual: induzir ou atrair alguém à prostituição ou outra forma de exploração sexual, facilitá-la, impedir ou dificultar que alguém a abandone. Pena: reclusão de 2 a 5 anos e multa. Se o agente é ascendente, padrasto, madrasta, irmão, enteado, cônjuge, companheiro, tutor, curador, preceptor ou empregador da vítima, ou assumiu obrigação de cuidado, proteção ou vigilância: reclusão de 3 a 8 anos. Com violência, grave ameaça ou fraude: reclusão de 4 a 10 anos, além da violência. Com fim de lucro: também multa.', '["Caput: reclusão de 2 a 5 anos e multa.","§1º: vínculo familiar, de autoridade ou de cuidado: 3 a 8 anos.","§2º: violência, grave ameaça ou fraude: 4 a 10 anos, além da violência.","§3º: fim de lucro: também multa."]'::jsonb, '["A PROSTITUIÇÃO em si não é crime; o crime é o favorecimento ou a exploração por terceiros."]'::jsonb, 'Pessoa impede, com ameaças, que uma mulher abandone a exploração sexual: art. 228, §2º.', '["Assertiva que considera crime o exercício da prostituição pela própria pessoa erra: o tipo pune quem a favorece ou explora."]'::jsonb, '[]'::jsonb, '["Arts. 218-B, 229 e 230"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-228'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Casa de exploração sexual: manter, por conta própria ou de terceiro, estabelecimento em que ocorra exploração sexual, haja ou não intuito de lucro ou mediação direta do proprietário ou gerente. Pena: reclusão de 2 a 5 anos e multa.', '["Manter estabelecimento em que ocorra exploração sexual.","Com ou sem intuito de lucro ou mediação direta.","Reclusão de 2 a 5 anos e multa."]'::jsonb, '["Independe de lucro."]'::jsonb, 'Dono de um imóvel mantém local onde se explora sexualmente pessoas.', '["Assertiva que exige intuito de lucro para o art. 229 erra: o tipo dispensa."]'::jsonb, '[]'::jsonb, '["Art. 228"]'::jsonb, 'under_review', 'claude'
