insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Rufianismo: tirar proveito da prostituição alheia, participando diretamente de seus lucros ou fazendo-se sustentar, no todo ou em parte, por quem a exerça. Pena: reclusão de 1 a 4 anos e multa. Se a vítima é menor de 18 e maior de 14 anos, ou se o agente é ascendente, padrasto, madrasta, irmão, enteado, cônjuge, companheiro, tutor, curador, preceptor ou empregador, ou assumiu dever de cuidado, proteção ou vigilância: reclusão de 3 a 6 anos e multa. Com violência, grave ameaça, fraude ou outro meio que impeça a livre manifestação da vontade: reclusão de 2 a 8 anos, sem prejuízo da violência.', '["Tirar proveito da prostituição alheia (participar dos lucros ou ser sustentado).","Caput: reclusão de 1 a 4 anos e multa.","§1º: vítima entre 14 e 18 anos ou vínculo de cuidado ou autoridade: reclusão de 3 a 6 anos e multa.","§2º: violência, grave ameaça, fraude ou outro meio: reclusão de 2 a 8 anos."]'::jsonb, '["Crime de quem VIVE à custa da prostituição de outra pessoa."]'::jsonb, 'Pessoa vive sustentada pelos ganhos da prostituição de outra e participa dos lucros.', '["Assertiva que pune a pessoa que exerce a prostituição por conta própria erra: o rufianismo pune quem tira proveito dela."]'::jsonb, '[{"termo":"Rufianismo","significado":"Viver às custas da prostituição alheia."}]'::jsonb, '["Art. 228"]'::jsonb, 'under_review', 'claude'
