insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Promoção de migração ilegal: promover, por qualquer meio, com o fim de obter vantagem econômica, a entrada ilegal de estrangeiro em território nacional ou de brasileiro em país estrangeiro. Pena: reclusão de 2 a 5 anos e multa. Na mesma pena quem promove, com o mesmo fim, a saída de estrangeiro do território nacional para ingressar ilegalmente em país estrangeiro. A pena aumenta de 1/6 a 1/3 se há violência ou se a vítima é submetida a condição desumana ou degradante, e é aplicada sem prejuízo das infrações conexas.', '["Promover entrada ilegal de estrangeiro no país ou de brasileiro em país estrangeiro, com vantagem econômica.","Reclusão de 2 a 5 anos e multa.","§1º: saída de estrangeiro para ingressar ilegalmente em outro país.","§2º: aumento de 1/6 a 1/3 (violência; condição desumana ou degradante).","§3º: sem prejuízo das infrações conexas."]'::jsonb, '["Exige FIM DE VANTAGEM ECONÔMICA."]'::jsonb, 'Pessoa cobra para levar estrangeiros ao Brasil por vias ilegais.', '["Assertiva que dispensa a finalidade de vantagem econômica no art. 232-A erra."]'::jsonb, '[]'::jsonb, '["Art. 149-A (tráfico de pessoas)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-232-a'
