insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Escrito ou objeto obsceno: fazer, importar, exportar, adquirir ou ter sob sua guarda, para fim de comércio, de distribuição ou de exposição pública, escrito, desenho, pintura, estampa ou qualquer objeto obsceno. Pena: detenção de 6 meses a 2 anos, ou multa. Na mesma pena quem vende, distribui ou expõe à venda ou ao público esses objetos; realiza, em lugar público ou acessível ao público, representação teatral ou exibição cinematográfica de caráter obsceno ou qualquer espetáculo do mesmo caráter; ou realiza, em lugar público ou acessível ao público, ou pelo rádio, audição ou recitação de caráter obsceno.', '["Fazer, importar, exportar, adquirir ou guardar objeto obsceno para comércio, distribuição ou exposição pública.","Detenção de 6 meses a 2 anos, ou multa.","Parágrafo único: vender, distribuir, expor; espetáculos, exibições, audições ou recitações obscenas em lugar público."]'::jsonb, '["O fim é comércio, distribuição ou exposição pública."]'::jsonb, 'Comerciante expõe à venda ao público objeto de caráter obsceno.', '["Assertiva que pune a posse de objeto obsceno para uso exclusivamente privado erra: o tipo exige fim de comércio, distribuição ou exposição."]'::jsonb, '[]'::jsonb, '["Art. 233"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-234'
