insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aumentos nos crimes sexuais do Título: de metade a 2/3 se do crime resulta gravidez; de 1/3 a 2/3 se o agente transmite à vítima doença sexualmente transmissível de que sabe ou deveria saber ser portador, ou se a vítima é idosa ou pessoa com deficiência. Os incisos I e II foram vetados.', '["III – gravidez: aumento de metade a 2/3.","IV – transmissão de DST que sabe ou deveria saber ser portador, ou vítima idosa ou com deficiência: 1/3 a 2/3."]'::jsonb, '["Gravidez: de METADE a 2/3; DST ou vítima idosa/com deficiência: de 1/3 a 2/3."]'::jsonb, 'Estupro de que resulta gravidez: pena aumentada de metade a 2/3.', '["Assertiva que fixa em 1/3 a 2/3 o aumento por gravidez erra: é de metade a 2/3."]'::jsonb, '[]'::jsonb, '["Art. 226"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-234-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Segredo de justiça: os processos em que se apuram crimes definidos no Título correrão em segredo de justiça. A partir da condenação em primeira instância pelos crimes dos arts. 213, 216-B, 217-A, 218-B, 227, 228, 229 e 230, o sistema de consulta processual torna público o nome completo do réu, seu CPF e a tipificação penal, com os dados da pena ou medida de segurança, salvo decisão fundamentada do juiz que mantenha o sigilo. Se absolvido em grau recursal, o sigilo é restabelecido. O réu condenado passa a ser monitorado por dispositivo eletrônico.', '["Processos em segredo de justiça.","§1º: após condenação em primeira instância (arts. 213, 216-B, 217-A, 218-B, 227, 228, 229 e 230): nome, CPF e tipificação passam a ser públicos.","§2º: absolvição em grau recursal restabelece o sigilo.","§3º: réu condenado monitorado por dispositivo eletrônico."]'::jsonb, '["A regra é o sigilo; a publicidade dos dados vem com a condenação em PRIMEIRA instância (salvo decisão em contrário)."]'::jsonb, 'Réu condenado por estupro em primeira instância tem nome e CPF públicos no sistema de consulta (salvo decisão contrária).', '["Assertiva que torna públicos os dados do réu antes de qualquer condenação erra."]'::jsonb, '[]'::jsonb, '["Art. 213","Art. 217-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-234-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Bigamia: contrair alguém, sendo casado, novo casamento. Pena: reclusão de 2 a 6 anos. Quem, não sendo casado, contrai casamento com pessoa casada, conhecendo essa circunstância, é punido com reclusão ou detenção de 1 a 3 anos. Anulado por qualquer motivo o primeiro casamento, ou o outro por motivo que não a bigamia, considera-se inexistente o crime.', '["Caput: casar-se sendo casado: reclusão de 2 a 6 anos.","§1º: casar-se com pessoa casada, conhecendo a circunstância: reclusão ou detenção de 1 a 3 anos.","§2º: anulado o primeiro casamento (ou o outro por outro motivo), inexiste o crime."]'::jsonb, '["O §1º exige que o outro contraente CONHEÇA o estado de casado."]'::jsonb, 'Pessoa já casada celebra novo casamento: bigamia.', '["Assertiva que pune o contraente do §1º mesmo sem conhecer o estado de casado do outro erra."]'::jsonb, '[]'::jsonb, '["Art. 111, IV (prescrição)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-235'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Induzimento a erro essencial e ocultação de impedimento: contrair casamento, induzindo em erro essencial o outro contraente, ou ocultando-lhe impedimento que não seja casamento anterior. Pena: detenção de 6 meses a 2 anos. A ação penal depende de queixa do contraente enganado e só pode ser intentada depois de transitar em julgado a sentença que, por erro ou impedimento, anule o casamento.', '["Induzir em erro essencial ou ocultar impedimento (que não seja casamento anterior).","Detenção de 6 meses a 2 anos.","Ação por QUEIXA, só após o trânsito em julgado da sentença que anule o casamento."]'::jsonb, '["Condição de procedibilidade: anulação do casamento transitada em julgado."]'::jsonb, 'Ocultar do cônjuge um impedimento ao casamento que o torna anulável.', '["Assertiva que permite a queixa antes da anulação transitada em julgado erra."]'::jsonb, '[]'::jsonb, '["Art. 235","Art. 237"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-236'
