select u.id, u.content_sha256, 'Conhecimento prévio de impedimento: contrair casamento, conhecendo a existência de impedimento que lhe cause a nulidade absoluta. Pena: detenção de 3 meses a 1 ano.', '["Casar-se conhecendo impedimento que gera nulidade absoluta.","Detenção de 3 meses a 1 ano."]'::jsonb, '["Exige CONHECIMENTO do impedimento."]'::jsonb, 'Casar-se com parente em grau proibido, sabendo do impedimento.', '["Assertiva que dispensa o conhecimento do impedimento no art. 237 erra."]'::jsonb, '[]'::jsonb, '["Art. 236"]'::jsonb, 'under_review', 'claude'
