select u.id, u.content_sha256, 'Registro de nascimento inexistente: promover no registro civil a inscrição de nascimento inexistente. Pena: reclusão de 2 a 6 anos.', '["Promover, no registro civil, inscrição de nascimento inexistente.","Reclusão de 2 a 6 anos."]'::jsonb, '["O nascimento é INEXISTENTE (diferente do art. 242, em que o filho existe)."]'::jsonb, 'Registrar no cartório o nascimento de uma criança que não nasceu.', '["Assertiva que aplica o art. 241 ao registro de filho de outrem como seu erra: isso é o art. 242."]'::jsonb, '[]'::jsonb, '["Art. 242"]'::jsonb, 'under_review', 'claude'
