insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Parto suposto e supressão ou alteração de direito inerente ao estado civil de recém-nascido: dar parto alheio como próprio; registrar como seu o filho de outrem; ocultar recém-nascido ou substituí-lo, suprimindo ou alterando direito inerente ao estado civil. Pena: reclusão de 2 a 6 anos. Se praticado por motivo de reconhecida nobreza: detenção de 1 a 2 anos, podendo o juiz deixar de aplicar a pena.', '["Condutas: dar parto alheio como próprio; registrar como seu filho de outrem; ocultar ou substituir recém-nascido.","Reclusão de 2 a 6 anos.","Parágrafo único: motivo de reconhecida nobreza: detenção de 1 a 2 anos, com possibilidade de perdão judicial."]'::jsonb, '["''Adoção à brasileira'': registrar filho alheio como seu, podendo ter o privilégio por nobreza."]'::jsonb, 'Pessoa registra como seu o filho recém-nascido de outra, sem adoção legal.', '["Assertiva que pune com reclusão de 2 a 6 anos o fato cometido por reconhecida nobreza erra: aplica-se o parágrafo único (detenção de 1 a 2 anos, com possível perdão judicial)."]'::jsonb, '[]'::jsonb, '["Art. 241","Art. 243"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-242'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sonegação de estado de filiação: deixar em asilo de expostos ou outra instituição de assistência filho próprio ou alheio, ocultando-lhe a filiação ou atribuindo-lhe outra, com o fim de prejudicar direito inerente ao estado civil. Pena: reclusão de 1 a 5 anos e multa.', '["Deixar filho (próprio ou alheio) em instituição, ocultando ou alterando a filiação.","Fim de prejudicar direito inerente ao estado civil.","Reclusão de 1 a 5 anos e multa."]'::jsonb, '["Exige o fim de prejudicar o estado civil."]'::jsonb, 'Deixar criança em instituição com filiação falsa para prejudicar seus direitos.', '["Assertiva que dispensa o fim de prejudicar direito inerente ao estado civil erra."]'::jsonb, '[]'::jsonb, '["Art. 242"]'::jsonb, 'under_review', 'claude'
