insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Abandono material: deixar, sem justa causa, de prover a subsistência do cônjuge, de filho menor de 18 anos ou inapto para o trabalho, ou de ascendente inválido ou maior de 60 anos, não lhes proporcionando os recursos necessários ou faltando ao pagamento de pensão alimentícia judicialmente acordada, fixada ou majorada; ou deixar, sem justa causa, de socorrer descendente ou ascendente gravemente enfermo. Pena: detenção de 1 a 4 anos e multa de uma a dez vezes o maior salário mínimo vigente. Nas mesmas penas incide quem, sendo solvente, frustra ou ilide o pagamento de pensão alimentícia, inclusive por abandono injustificado de emprego ou função.', '["Deixar de prover a subsistência de cônjuge, filho menor de 18 ou inapto, ascendente inválido ou maior de 60 anos.","Faltar ao pagamento de pensão alimentícia judicial.","Deixar de socorrer descendente ou ascendente gravemente enfermo.","Detenção de 1 a 4 anos e multa de uma a dez vezes o maior salário mínimo.","Parágrafo único: quem, sendo solvente, frustra o pagamento da pensão (inclusive por abandono de emprego)."]'::jsonb, '["Exige AUSÊNCIA de justa causa.","O parágrafo único trata do devedor SOLVENTE que frustra o pagamento."]'::jsonb, 'Pai deixa de pagar, sem justa causa, a pensão alimentícia fixada em juízo, embora possa pagar.', '["Assertiva que pune o devedor de pensão que está sem condições de pagar por justa causa erra: o tipo exige ausência de justa causa."]'::jsonb, '[]'::jsonb, '["Art. 245"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-244'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Entrega de filho menor a pessoa inidônea: entregar filho menor de 18 anos a pessoa em cuja companhia saiba ou deva saber que o menor fica moral ou materialmente em perigo. Pena: detenção de um a dois anos. Se o agente pratica o delito para obter lucro, ou se o menor é enviado para o exterior: reclusão de um a quatro anos. Incorre na mesma pena quem, embora excluído o perigo, auxilia ato destinado ao envio de menor para o exterior com o fito de lucro.', '["Entregar filho menor de 18 anos a pessoa inidônea.","Detenção de um a dois anos.","§1º: fim de lucro ou envio ao exterior: reclusão de um a quatro anos.","§2º: auxiliar o envio de menor ao exterior com fito de lucro, mesmo sem perigo."]'::jsonb, '["Exige que o agente SAIBA ou DEVA SABER do perigo moral ou material."]'::jsonb, 'Pai entrega o filho a uma pessoa que sabe explorá-lo.', '["Assertiva que dispensa que o agente saiba ou deva saber do perigo erra."]'::jsonb, '[]'::jsonb, '["Art. 244","Art. 249"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-245'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

