select u.id, u.content_sha256, 'Abandono intelectual: deixar, sem justa causa, de prover à instrução primária de filho em idade escolar. Pena: detenção de quinze dias a um mês, ou multa.', '["Deixar de prover a instrução primária de filho em idade escolar.","Sem justa causa.","Detenção de quinze dias a um mês, ou multa."]'::jsonb, '["Exige ausência de justa causa."]'::jsonb, 'Pai que, podendo, não matricula o filho em idade escolar.', '["Assertiva que pune o fato mesmo havendo justa causa erra."]'::jsonb, '[]'::jsonb, '["Art. 244"]'::jsonb, 'under_review', 'claude'
