insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Abandono moral: permitir alguém que menor de dezoito anos, sujeito a seu poder ou confiado à sua guarda ou vigilância, frequente casa de jogo ou mal-afamada, ou conviva com pessoa viciosa ou de má vida; frequente espetáculo capaz de pervertê-lo ou de ofender-lhe o pudor; resida ou trabalhe em casa de prostituição; ou mendigue ou sirva a mendigo para excitar a comiseração pública. Pena: detenção de um a três meses, ou multa.', '["Permitir que o menor frequente casa de jogo, mal-afamada ou conviva com pessoa viciosa.","Permitir espetáculo que o perverta ou ofenda o pudor.","Permitir que resida ou trabalhe em casa de prostituição.","Permitir que mendigue ou sirva a mendigo.","Detenção de um a três meses, ou multa."]'::jsonb, '["O crime é PERMITIR, ou seja, omissão de quem tem poder, guarda ou vigilância."]'::jsonb, 'Responsável permite que o menor trabalhe em casa de prostituição.', '["Assertiva que aplica o art. 247 a qualquer pessoa, sem poder, guarda ou vigilância sobre o menor, erra."]'::jsonb, '[]'::jsonb, '["Art. 218-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-247'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Induzimento a fuga, entrega arbitrária ou sonegação de incapazes: induzir menor de dezoito anos, ou interdito, a fugir do lugar em que se acha por determinação de quem sobre ele exerce autoridade; confiar a outrem, sem ordem do pai, do tutor ou do curador, algum menor de dezoito anos ou interdito; ou deixar, sem justa causa, de entregá-lo a quem legitimamente o reclame. Pena: detenção de um mês a um ano, ou multa.', '["Induzir menor ou interdito a fugir.","Confiar menor ou interdito a outrem sem ordem do responsável.","Deixar de entregá-lo, sem justa causa, a quem legitimamente o reclame.","Detenção de um mês a um ano, ou multa."]'::jsonb, '["Três condutas no mesmo artigo."]'::jsonb, 'Pessoa se recusa, sem justa causa, a devolver o menor a quem legitimamente o reclama.', '["Assertiva que pune a conduta de entregar o menor a quem legitimamente o reclame erra: o crime é deixar de entregar."]'::jsonb, '[]'::jsonb, '["Art. 249"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-248'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Subtração de incapazes: subtrair menor de dezoito anos ou interdito ao poder de quem o tem sob sua guarda em virtude de lei ou de ordem judicial. Pena: detenção de dois meses a dois anos, se o fato não constitui elemento de outro crime. Ser o agente pai ou tutor do menor ou curador do interdito não o exime de pena, se destituído ou temporariamente privado do poder, tutela, curatela ou guarda. Se há restituição do menor ou do interdito sem maus-tratos ou privações, o juiz pode deixar de aplicar pena.', '["Subtrair menor ou interdito de quem o tem sob guarda legal ou judicial.","Detenção de dois meses a dois anos, se não for elemento de outro crime.","§1º: pai ou tutor destituído ou privado temporariamente também responde.","§2º: restituição sem maus-tratos ou privações: perdão judicial."]'::jsonb, '["Crime subsidiário.","O próprio pai pode ser sujeito ativo se perdeu a guarda."]'::jsonb, 'Pai privado da guarda por decisão judicial leva o filho sem autorização.', '["Assertiva que isenta o pai de qualquer responsabilidade no art. 249 erra: se destituído ou privado da guarda, responde."]'::jsonb, '[]'::jsonb, '["Art. 248"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-249'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incêndio: causar incêndio, expondo a perigo a vida, a integridade física ou o patrimônio de outrem. Pena: reclusão de três a seis anos e multa. As penas aumentam-se de um terço se o crime é cometido com intuito de obter vantagem pecuniária, ou se o incêndio é em casa habitada ou destinada a habitação; em edifício público ou de uso público, obra de assistência social ou de cultura; em embarcação, aeronave, comboio ou veículo de transporte coletivo; em estação ferroviária ou aeródromo; em estaleiro, fábrica ou oficina; em depósito de explosivo, combustível ou inflamável; em poço petrolífico ou galeria de mineração; ou em lavoura, pastagem, mata ou floresta. Se culposo: detenção de seis meses a dois anos.', '["Causar incêndio, expondo a perigo vida, integridade física ou patrimônio de outrem.","Reclusão de três a seis anos e multa.","§1º: aumento de um terço (vantagem pecuniária; locais e meios listados).","§2º: culposo: detenção de seis meses a dois anos."]'::jsonb, '["É crime de PERIGO COMUM: exige perigo concreto a pessoas ou patrimônio.","Há modalidade culposa."]'::jsonb, 'Incendiar um edifício público expondo pessoas a perigo.', '["Assertiva que dispensa a exposição a perigo no crime de incêndio erra."]'::jsonb, '[{"termo":"Crime de perigo comum","significado":"Atinge número indeterminado de pessoas ou coisas."}]'::jsonb, '["Art. 251","Art. 258"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-250'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Explosão: expor a perigo a vida, a integridade física ou o patrimônio de outrem, mediante explosão, arremesso ou simples colocação de engenho de dinamite ou de substância de efeitos análogos. Pena: reclusão de três a seis anos e multa. Se a substância não é dinamite ou explosivo de efeitos análogos: reclusão de um a quatro anos e multa. As penas aumentam-se de um terço nas hipóteses do art. 250, §1º, I ou II. No caso de culpa: detenção de seis meses a dois anos, se a explosão é de dinamite ou substância análoga; nos demais casos, de três meses a um ano.', '["Expor a perigo mediante explosão, arremesso ou colocação de engenho.","Dinamite ou análoga: reclusão de três a seis anos e multa.","§1º: outra substância: reclusão de um a quatro anos e multa.","§2º: aumento de um terço nas hipóteses do art. 250.","§3º: culposo: detenção de seis meses a dois anos (dinamite) ou de três meses a um ano (demais)."]'::jsonb, '["A pena varia conforme a substância usada."]'::jsonb, 'Detonar dinamite em local movimentado expondo pessoas a perigo.', '["Assertiva que aplica a mesma pena para dinamite e para outras substâncias erra."]'::jsonb, '[]'::jsonb, '["Art. 250","Art. 258"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-251'
