select u.id, u.content_sha256, 'Uso de gás tóxico ou asfixiante: expor a perigo a vida, a integridade física ou o patrimônio de outrem, usando de gás tóxico ou asfixiante. Pena: reclusão de um a quatro anos e multa. Se culposo: detenção de três meses a um ano.', '["Expor a perigo usando gás tóxico ou asfixiante.","Reclusão de um a quatro anos e multa.","Culposo: detenção de três meses a um ano."]'::jsonb, '["Há modalidade culposa."]'::jsonb, 'Liberar gás tóxico em ambiente fechado com pessoas.', '["Assertiva que nega a modalidade culposa no art. 252 erra."]'::jsonb, '[]'::jsonb, '["Art. 253"]'::jsonb, 'under_review', 'claude'
