insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fabrico, fornecimento, aquisição, posse ou transporte de explosivos ou gás tóxico ou asfixiante: fabricar, fornecer, adquirir, possuir ou transportar, sem licença da autoridade, substância ou engenho explosivo, gás tóxico ou asfixiante, ou material destinado à sua fabricação. Pena: detenção de seis meses a dois anos e multa.', '["Fabricar, fornecer, adquirir, possuir ou transportar sem licença.","Objeto: explosivo, gás tóxico ou asfixiante, ou material para fabricação.","Detenção de seis meses a dois anos e multa."]'::jsonb, '["Exige ausência de LICENÇA da autoridade."]'::jsonb, 'Transportar explosivo sem licença da autoridade.', '["Assertiva que dispensa a ausência de licença no art. 253 erra."]'::jsonb, '[]'::jsonb, '["Art. 251","Art. 252"]'::jsonb, 'under_review', 'claude'
