select u.id, u.content_sha256, 'Subtração, ocultação ou inutilização de material de salvamento: subtrair, ocultar ou inutilizar, por ocasião de incêndio, inundação, naufrágio ou outro desastre ou calamidade, aparelho, material ou qualquer meio destinado a serviço de combate ao perigo, de socorro ou salvamento; ou impedir ou dificultar serviço de tal natureza. Pena: reclusão de dois a cinco anos e multa.', '["Subtrair, ocultar ou inutilizar material de socorro ou salvamento.","Ou impedir/dificultar serviço de socorro.","Por ocasião de desastre ou calamidade.","Reclusão de dois a cinco anos e multa."]'::jsonb, '["Exige que ocorra por OCASIÃO de desastre ou calamidade."]'::jsonb, 'Esconder equipamento de combate ao fogo durante um incêndio.', '["Assertiva que dispensa o contexto de desastre ou calamidade erra."]'::jsonb, '[]'::jsonb, '["Art. 250"]'::jsonb, 'under_review', 'claude'
