insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Formas qualificadas de crime de perigo comum: se do crime doloso de perigo comum resulta lesão corporal de natureza grave, a pena privativa de liberdade é aumentada de metade; se resulta morte, é aplicada em dobro. No caso de culpa, se do fato resulta lesão corporal, a pena aumenta-se de metade; se resulta morte, aplica-se a pena cominada ao homicídio culposo, aumentada de um terço.', '["Doloso + lesão grave: aumento de metade.","Doloso + morte: pena em dobro.","Culposo + lesão corporal: aumento de metade.","Culposo + morte: pena do homicídio culposo, aumentada de um terço."]'::jsonb, '["Diferencie o resultado agravador no crime doloso e no culposo."]'::jsonb, 'Incêndio doloso do qual resulta morte tem a pena em dobro.', '["Assertiva que aplica a pena em dobro no crime culposo com morte erra: aplica-se a pena do homicídio culposo aumentada de um terço."]'::jsonb, '[]'::jsonb, '["Art. 250","Art. 263"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-258'
