insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Difusão de doença ou praga: difundir doença ou praga que possa causar dano a floresta, plantação ou animais de utilidade econômica. Pena: reclusão de dois a cinco anos e multa. No caso de culpa: detenção de um a seis meses, ou multa.', '["Difundir doença ou praga que cause dano a floresta, plantação ou animais de utilidade econômica.","Reclusão de dois a cinco anos e multa.","Culposo: detenção de um a seis meses, ou multa."]'::jsonb, '["O objeto protegido é de utilidade econômica."]'::jsonb, 'Espalhar praga que atinge lavouras da região.', '["Assertiva que aplica o art. 259 a doença que ataca pessoas erra: o tipo protege floresta, plantação e animais."]'::jsonb, '[]'::jsonb, '["Art. 267"]'::jsonb, 'under_review', 'claude'
