on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Perigo de desastre ferroviário: impedir ou perturbar serviço de estrada de ferro destruindo, danificando ou desarranjando linha férrea, material rodante ou de tração, obra-de-arte ou instalação; colocando obstáculo na linha; transmitindo falso aviso acerca do movimento dos veículos ou interrompendo ou embaraçando o funcionamento de telégrafo, telefone ou radiotelegrafia; ou praticando outro ato de que possa resultar desastre. Pena: reclusão de dois a cinco anos e multa. Se resulta desastre: reclusão de quatro a doze anos e multa. No caso de culpa, ocorrendo desastre: detenção de seis meses a dois anos. Estrada de ferro: qualquer via em que circulem veículos de tração mecânica, em trilhos ou por meio de cabo aéreo.', '["Impedir ou perturbar serviço de estrada de ferro por quatro meios.","Reclusão de dois a cinco anos e multa.","§1º: resulta desastre: reclusão de quatro a doze anos e multa.","§2º: culposo com desastre: detenção de seis meses a dois anos.","§3º: conceito de estrada de ferro."]'::jsonb, '["O conceito de estrada de ferro inclui cabo aéreo."]'::jsonb, 'Colocar obstáculo na linha férrea.', '["Assertiva que restringe o conceito de estrada de ferro a trilhos erra: inclui cabo aéreo."]'::jsonb, '[]'::jsonb, '["Art. 261","Art. 263"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-260'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Atentado contra a segurança de transporte marítimo, fluvial ou aéreo: expor a perigo embarcação ou aeronave, própria ou alheia, ou praticar qualquer ato tendente a impedir ou dificultar navegação marítima, fluvial ou aérea. Pena: reclusão de dois a cinco anos. Se resulta naufrágio, submersão ou encalhe de embarcação ou queda ou destruição de aeronave: reclusão de quatro a doze anos. Com intuito de vantagem econômica: também multa. No caso de culpa, se ocorre o sinistro: detenção de seis meses a dois anos.', '["Expor a perigo embarcação ou aeronave, ou dificultar navegação.","Reclusão de dois a cinco anos.","§1º: sinistro (naufrágio, submersão, encalhe, queda ou destruição): reclusão de quatro a doze anos.","§2º: fim de lucro: também multa.","§3º: culposo com sinistro: detenção de seis meses a dois anos."]'::jsonb, '["Embarcação ou aeronave própria ou alheia."]'::jsonb, 'Sabotar aeronave expondo-a a perigo.', '["Assertiva que limita o art. 261 a embarcação ou aeronave alheia erra: vale também a própria."]'::jsonb, '[]'::jsonb, '["Art. 260","Art. 262"]'::jsonb, 'under_review', 'claude'
