insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Atentado contra a segurança de outro meio de transporte: expor a perigo outro meio de transporte público, impedir-lhe ou dificultar-lhe o funcionamento. Pena: detenção de um a dois anos. Se resulta desastre: reclusão de dois a cinco anos. No caso de culpa, se ocorre desastre: detenção de três meses a um ano.', '["Expor a perigo outro meio de transporte público.","Detenção de um a dois anos.","§1º: resulta desastre: reclusão de dois a cinco anos.","§2º: culposo com desastre: detenção de três meses a um ano."]'::jsonb, '["Abrange meios de transporte público diversos de trem, embarcação e aeronave."]'::jsonb, 'Sabotar ônibus de transporte público para dificultar seu funcionamento.', '["Assertiva que aplica o art. 262 a transporte privado erra: o tipo exige transporte público."]'::jsonb, '[]'::jsonb, '["Art. 260","Art. 261"]'::jsonb, 'under_review', 'claude'
