insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Arremesso de projétil: arremessar projétil contra veículo, em movimento, destinado ao transporte público por terra, por água ou pelo ar. Pena: detenção de um a seis meses. Se resulta lesão corporal: detenção de seis meses a dois anos; se resulta morte, a pena é a do art. 121, §3º, aumentada de um terço.', '["Arremessar projétil contra veículo de transporte público em movimento.","Detenção de um a seis meses.","Lesão corporal: detenção de seis meses a dois anos.","Morte: pena do art. 121, §3º, aumentada de um terço."]'::jsonb, '["O veículo deve estar EM MOVIMENTO e ser de transporte público."]'::jsonb, 'Atirar pedra contra ônibus em movimento.', '["Assertiva que aplica o art. 264 a veículo parado erra."]'::jsonb, '[]'::jsonb, '["Art. 121, §3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-264'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Atentado contra a segurança de serviço de utilidade pública: atentar contra a segurança ou o funcionamento de serviço de água, luz, força ou calor, ou qualquer outro de utilidade pública. Pena: reclusão de um a cinco anos e multa. Aumenta-se a pena de 1/3 até a metade se o dano ocorrer em virtude de subtração de material essencial ao funcionamento dos serviços.', '["Atentar contra a segurança ou o funcionamento de serviço de utilidade pública.","Reclusão de um a cinco anos e multa.","Parágrafo único: subtração de material essencial: aumento de 1/3 até a metade."]'::jsonb, '["Serviços como água, luz, força ou calor."]'::jsonb, 'Subtrair cabos essenciais que causam interrupção do serviço de energia.', '["Assertiva que fixa o aumento em dobro na subtração de material essencial erra: é de 1/3 até a metade."]'::jsonb, '[]'::jsonb, '["Art. 266"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-265'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Interrupção ou perturbação de serviço telegráfico, telefônico, informático, telemático ou de informação de utilidade pública: interromper ou perturbar serviço telegráfico, radiotelegráfico ou telefônico, impedir ou dificultar-lhe o restabelecimento. Pena: reclusão de 2 a 4 anos e multa (Lei nº 15.397, de 2026). Na mesma pena quem interrompe serviço telemático ou de informação de utilidade pública, ou impede ou dificulta o restabelecimento. As penas se aplicam em dobro se o crime é cometido por ocasião de calamidade pública ou mediante subtração, dano ou destruição de equipamento instalado em estrutura utilizada para telecomunicações.', '["Interromper ou perturbar serviço telegráfico, radiotelegráfico ou telefônico.","Reclusão de 2 a 4 anos e multa.","§1º: serviço telemático ou de informação de utilidade pública.","§2º: penas em dobro (calamidade pública; subtração, dano ou destruição de equipamento de telecomunicações)."]'::jsonb, '["Conferir a redação vigente, pois a pena foi alterada em 2026."]'::jsonb, 'Derrubar serviço de internet de utilidade pública durante calamidade pública: penas em dobro.', '["Assertiva que não prevê aumento por calamidade pública erra: as penas se aplicam em dobro."]'::jsonb, '[]'::jsonb, '["Art. 265"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-266'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Epidemia: causar epidemia, mediante a propagação de germes patogênicos. Se do fato resulta morte, a pena é aplicada em dobro. No caso de culpa: detenção de um a dois anos, ou, se resulta morte, de dois a quatro anos.', '["Causar epidemia mediante propagação de germes patogênicos.","§1º: resulta morte: pena em dobro.","§2º: culposo: detenção de um a dois anos, ou de dois a quatro anos se resulta morte."]'::jsonb, '["Crime hediondo na forma dolosa com resultado morte (conforme a Lei dos Crimes Hediondos)."]'::jsonb, 'Propagar deliberadamente germes patogênicos entre a população.', '["Assertiva que afasta a modalidade culposa da epidemia erra."]'::jsonb, '[{"termo":"Germes patogênicos","significado":"Microrganismos capazes de causar doença."}]'::jsonb, '["Art. 268"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-267'
